import{_ as t,o as a,c as s,a5 as i}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Transports actuels et restrictions de plateforme","description":"","frontmatter":{"title":"Transports actuels et restrictions de plateforme","docId":"developer.transports","translationKey":"developer.transports","locale":"fr","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6696987a0db16b3b4d364c6136d0e552dbebd6fc68346e3ed031587a7b004468","translationRevision":"cd19861926e83262ae0bb4f662b00a7a2a9121fb3c1e3cdda508a77bdffe9ec7","order":200},"headers":[],"relativePath":"fr/developer/transports.md","filePath":"fr/developer/transports.md","lastUpdated":1794611623000}'),r={name:"fr/developer/transports.md"};function n(o,e,l,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">Transports actuels et restrictions de plateforme <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;Transports actuels et restrictions de plateforme {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Choisir le transport qui existe réellement pour la compilation et la plateforme ciblées. Lisez l’<a href="./control-api.html">API de contrôle</a> et la <a href="./collaboration.html">collaboration</a>. Un transport porte des opérations sérialisées ; il ne doit pas introduire un second cœur ou accorder une autorité à lui seul.</p><h2 id="choose-the-boundary" tabindex="-1">Choisir la frontière <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;Choisir la frontière {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parcours</th><th>Implémentation actuelle</th><th>Limite importante</th></tr></thead><tbody><tr><td>WebView de bureau</td><td>IPC Wry et client de contrôle partagé</td><td>La durée de vie de l’interface/des threads appartient au bureau</td></tr><tr><td>CLI locale</td><td>Socket Unix ou tube nommé Windows ; hôte stdio explicite</td><td>Même répertoire d’application et même propriétaire</td></tr><tr><td>Navigateur local</td><td>Adaptateur natif de bouclage et <code>browser-transport.ts</code></td><td>Hôte natif appairé, pas de simulacre ni de serveur distant public</td></tr><tr><td>Distant direct</td><td>Passerelle HTTPS/WSS authentifiée et transports SDK/navigateur</td><td>TLS, hello, autorisations et conditions de fonctionnalités</td></tr><tr><td>Pair natif</td><td><code>tiktools-peer</code>, flux iroh/QUIC chiffré</td><td>L’identité du pair ne confère pas l’autorité RPC</td></tr><tr><td>WebRTC natif</td><td><code>tiktools-rtc</code>, signalisation signée et canaux de données</td><td>Les vérifications de négociation, autorisation et route restent nécessaires</td></tr></tbody></table><p>L’interface TypeScript de transport se trouve dans <code>src/web/shared/api/control-transport.ts</code>. La configuration de pair natif n’active pas implicitement des relais tiers publics ou la découverte. WebRTC est natif Rust (<code>webrtc</code> 0.21.1), sans dépendance à <code>RTCPeerConnection</code> du navigateur dans l’interface de bureau.</p><h2 id="inspect-the-selected-route" tabindex="-1">Examiner la route sélectionnée <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;Examiner la route sélectionnée {#inspect-the-selected-route}&quot;">​</a></h2><p>Découvrez les méthodes et capacités prises en charge par l’hôte connecté avant d’appairer ou d’afficher une action de contrôleur :</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote-browser-transport</span></span></code></pre></div><p><code>tiktools-rtc/src/route.rs</code> observe la paire de candidats ICE sélectionnée pour classer la route comme directe ou relayée. Un état prêt seul ne prouve pas une route directe. L’infrastructure de signalisation/relais Cloud est distincte de l’autorisation métier et doit conserver les vérifications natives d’autorisation.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>L’IPC local et le transport de bureau sont des parcours établis. Le pair natif, WebRTC et l’intégration contrôleur disposent de code et de tests ciblés, mais le déploiement et la validation multi-PC restent expérimentaux. Les anciens textes affirmant l’absence d’implémentation pair/relais sont historiques. L’IPC local Android fonctionne ; les profils distants persistants n’ont pas de coffre d’identifiants sélectionné et les extensions natives/WebViews de bureau y restent indisponibles.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Traitez une déconnexion comme une possible incertitude pour les opérations acceptées. La reconnexion doit invalider les projections privées, renégocier l’identité et reprendre les flux bornés ou en obtenir un instantané. N’affaiblissez jamais les vérifications de certificat et ne vous repliez pas silencieusement vers un propriétaire local après un échec distant. L’<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-rtc/src" target="_blank" rel="noreferrer">implémentation RTC</a> et le graphe réel des fonctionnalités priment sur les anciens plans de transport.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Peer utilise ALPN <code>tiktools/collaboration/1</code>, un délai actuel de 15 s et au plus quatre relais explicitement configurés. Les trames Peer/RTC sont limitées à 1 MiB ; RTC fragmente en paquets d’au plus 16 KiB. Une trame trop grande échoue à la validation, sans RPC partiel. Diagnostiquez séparément configuration/identité, signalisation, délai, taille et autorisation. Le relais Cloud n’est pas un serveur TURN ICE ; une liste vide n’active pas la découverte publique. Vérifiez hôte/appareil actifs et permission confirmée actuelle, puis notez la route ICE directe ou relayée. Un transport ready/chiffré ne prouve ni autorité RPC ni traversée de tout NAT. Testez révocation/changement de session et trames excessives avant deux vrais PC.</p>`,16)])])}const f=t(r,[["render",n]]);export{h as __pageData,f as default};
